('058a8fdc-1144-4f67-9650-e5eda1565e81'::uuid,3,'business','倉庫の隅に不要な箱を置かないでください。','Xin đừng để hộp không cần thiết ở góc kho.','倉庫の＿＿＿に不要な箱を置かないでください。','隅',1,'倉庫・部屋の隅.'),
('82ce8d6b-a403-48ef-af16-857e88d3347b'::uuid,1,'exam','非常時にはこの出口を使ってください。','Trong trường hợp khẩn cấp hãy sử dụng lối ra này.','＿＿＿にはこの出口を使ってください。','非常時',1,'非常時には～＝trong tình huống khẩn cấp.'),
('82ce8d6b-a403-48ef-af16-857e88d3347b'::uuid,3,'business','非常時の連絡方法を全員で確認します。','Tất cả sẽ cùng xác nhận phương thức liên lạc khi khẩn cấp.','＿＿＿の連絡方法を全員で確認します。','非常時',1,'非常時の連絡先／対応.'),
('720ef99c-d625-4b5d-87f7-eae53074e3af'::uuid,1,'exam','非常袋には水や食べ物を入れておきます。','Trong túi khẩn cấp nên để sẵn nước và thức ăn.','＿＿＿には水や食べ物を入れておきます。','非常袋',1,'非常袋を用意する／中にNを入れる.'),
('720ef99c-d625-4b5d-87f7-eae53074e3af'::uuid,3,'business','事務所の非常袋を毎年点検します。','Chúng tôi kiểm tra túi khẩn cấp của văn phòng mỗi năm.','事務所の＿＿＿を毎年点検します。','非常袋',1,'防災管理の文脈.'),
('a363a6ee-98e2-41c3-9337-d0deb9514738'::uuid,1,'exam','誕生日なので、部屋を風船で飾りました。','Vì sinh nhật nên tôi đã trang trí phòng bằng bóng bay.','誕生日なので、部屋を風船で＿＿＿。','飾りました',1,'場所をNで飾る／Nを飾る.'),
('a363a6ee-98e2-41c3-9337-d0deb9514738'::uuid,3,'business','受付を季節の花で飾ります。','Chúng tôi trang trí quầy lễ tân bằng hoa theo mùa.','受付を季節の花で＿＿＿。','飾ります',1,'受付／会場を飾る.'),
('5160ebc4-e4d7-42a1-8b62-a98f3b206166'::uuid,1,'exam','ガイドブックで観光地を調べました。','Tôi tra các điểm du lịch trong sách hướng dẫn.','＿＿＿で観光地を調べました。','ガイドブック',1,'ガイドブックを見る／買う／調べる.'),
('5160ebc4-e4d7-42a1-8b62-a98f3b206166'::uuid,3,'business','ホテルの情報をガイドブックに掲載します。','Chúng tôi đăng thông tin khách sạn vào sách hướng dẫn.','ホテルの情報を＿＿＿に掲載します。','ガイドブック',2,'情報をガイドブックに載せる／掲載する.'),
('1e67257c-e319-4e0a-a31e-6765404f2cd0'::uuid,1,'exam','試験の日をカレンダーに書きました。','Tôi đã ghi ngày thi vào lịch.','試験の日を＿＿＿に書きました。','カレンダー',1,'カレンダーに予定を書く／見る.'),
('1e67257c-e319-4e0a-a31e-6765404f2cd0'::uuid,3,'business','会議日を共有カレンダーに登録します。','Tôi sẽ đăng ký ngày họp vào lịch dùng chung.','会議日を共有＿＿＿に登録します。','カレンダー',2,'共有カレンダーに予定を登録する.'),
('ee5e84e5-f6ae-4266-afe7-02e8ddc880bf'::uuid,1,'exam','駅にイベントのポスターが貼ってありました。','Ở ga có dán poster sự kiện.','駅にイベントの＿＿＿が貼ってありました。','ポスター',1,'ポスターを貼る／作る.'),
('ee5e84e5-f6ae-4266-afe7-02e8ddc880bf'::uuid,3,'business','安全週間のポスターを社内に貼ります。','Chúng tôi sẽ dán poster tuần lễ an toàn trong công ty.','安全週間の＿＿＿を社内に貼ります。','ポスター',1,'社内掲示のポスター.'),
('f6c39b7b-b2ab-4531-ac1b-aa6b23c70927'::uuid,1,'exam','ミーティングが終わったら、昼ご飯を食べましょう。','Sau khi cuộc họp kết thúc, chúng ta ăn trưa nhé.','＿＿＿が終わったら、昼ご飯を食べましょう。','ミーティング',1,'ミーティングをする／ミーティングがある.'),
('f6c39b7b-b2ab-4531-ac1b-aa6b23c70927'::uuid,3,'business','午後三時からチームミーティングがあります。','Từ 3 giờ chiều có cuộc họp nhóm.','午後三時からチーム＿＿＿があります。','ミーティング',1,'チームミーティング／オンラインミーティング.'),
('cb5ecc4d-b3b0-45c2-bd79-477f6771f50c'::uuid,1,'exam','荷物が多いので、大きなリュックを持って行きます。','Vì có nhiều đồ nên tôi sẽ mang ba lô lớn.','荷物が多いので、大きな＿＿＿を持って行きます。','リュック',1,'リュックを背負う／持つ.'),
('cb5ecc4d-b3b0-45c2-bd79-477f6771f50c'::uuid,3,'business','出張にはパソコンが入るリュックを使います。','Khi đi công tác tôi dùng ba lô có thể đựng máy tính.','出張にはパソコンが入る＿＿＿を使います。','リュック',1,'通勤・出張のリュック.'),
('5808207f-e32b-4c12-8fa2-6977ae54c816'::uuid,1,'exam','昨夜、昔の友達に会う夢を見ました。','Đêm qua tôi mơ thấy gặp người bạn cũ.','昨夜、昔の友達に会う＿＿＿。','夢を見ました',2,'夢を見る＝mơ; 夢がある＝có ước mơ là nghĩa khác.'),
('5808207f-e32b-4c12-8fa2-6977ae54c816'::uuid,3,'business','仕事で失敗する夢を見て、目が覚めました。','Tôi mơ thấy mình thất bại trong công việc rồi tỉnh giấc.','仕事で失敗する＿＿＿、目が覚めました。','夢を見て',2,'literal sleep dream, not aspiration.')
)
insert into public.jp_vocab_examples(vocab_id,example_no,example_type,example_jp,example_vi,cloze_jp,answer,source_type,difficulty,focus_note)
select r.vocab_id,r.example_no,r.example_type,r.example_jp,r.example_vi,r.cloze_jp,r.answer,'generated',r.difficulty,r.focus_note
from rows r where not exists(select 1 from public.jp_vocab_examples e where e.vocab_id=r.vocab_id and e.example_type=r.example_type);
